importScripts('solver-core.js');
const {solveExact,solveRestrictedHorizon,matchMask,strictMatchMask,isExactAnswer,compare}=self.DecoderSolver;
const FIELDS=[{key:'border',bit:1},{key:'attribute',bit:2},{key:'race',bit:4},{key:'number',bit:8},{key:'attack',bit:16},{key:'defense',bit:32}];
let cancelled=false,lastPulse=0;
