const popcount=(mask)=>{let n=0;for(let v=mask&63;v;v&=v-1)n+=1;return n};
const read=(card,key)=>({border:card.b,attribute:card.a,race:card.r,number:card.n,attack:card.atk,defense:card.def})[key];
const entropy=(p)=>p<=0||p>=1?0:-p*Math.log2(p)-(1-p)*Math.log2(1-p);
function percentile(sorted,f){return sorted[Math.min(sorted.length-1,Math.max(0,Math.round((sorted.length-1)*f)))]||0}
function summarize(results,puzzles,diagnostics,startedAt){
 const average=(key)=>results.length?results.reduce((s,x)=>s+x[key],0)/results.length:0;
 const solved=results.map(x=>x.solved).sort((a,b)=>a-b),mean=average('solved');
 const variance=results.length>1?results.reduce((s,x)=>s+(x.solved-mean)**2,0)/(results.length-1):0,margin=1.96*Math.sqrt(variance/Math.max(1,results.length));
 const completed=results.filter(x=>x.solved===puzzles).length,p=completed/Math.max(1,results.length),z=1.96,n=Math.max(1,results.length);
 const center=(p+z*z/(2*n))/(1+z*z/n),wm=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/(1+z*z/n);
 return {count:results.length,meanSolved:mean,solvedLow:Math.max(0,mean-margin),solvedHigh:Math.min(puzzles,mean+margin),p10:percentile(solved,.1),p50:percentile(solved,.5),p90:percentile(solved,.9),completion:p,completionLow:Math.max(0,center-wm),completionHigh:Math.min(1,center+wm),matchedItems:average('matchedItems'),hintsUsed:average('hintsUsed'),challengesUsed:average('challengesUsed'),distribution:Array.from({length:puzzles+1},(_,value)=>({solved:value,count:results.filter(x=>x.solved===value).length})).filter(x=>x.count),diagnostics,elapsed:(performance.now()-startedAt)/1000};
}
function weightedSample(items,weights){let total=0;for(const i of items)total+=weights[i];let draw=Math.random()*total;for(const i of items){draw-=weights[i];if(draw<0)return i}return items.at(-1)}
function filterCandidates(cards,candidates,guess,mask,target){return candidates.filter(i=>{const card=cards[i];return matchMask(card,guess)===mask&&(!(mask&1)||card.b===target.b)&&(!(mask&8)||card.n===target.n)})}
function stateKey(candidates,knownMask,matchedMask,guessed,hints,challenges,puzzle){return `${puzzle}|${hints}|${challenges}|${knownMask}|${matchedMask}|${candidates.join(',')}|${[...guessed].sort((a,b)=>a-b).join(',')}`}

// Independent resource-route policy. This mirrors resource-route-worker.js so
// simulation and manual recommendations compare the same two first actions.
const rrBit=i=>1<<i,rrEnt=p=>p<=0||p>=1?0:-p*Math.log2(p)-(1-p)*Math.log2(1-p),rrMass=xs=>xs.reduce((s,i)=>s+rrWeights[i],0);
const rrWeak=(t,g)=>{let m=0;if((t.b&128)?!!(t.b&g.b&127):t.b===g.b)m|=1;if(t.a===g.a)m|=2;if(t.r===g.r)m|=4;if(t.nm&g.nm)m|=8;if(t.atk===g.atk)m|=16;if(t.def===g.def)m|=32;return m};
const rrStrict=(t,g)=>(rrWeak(t,g)&~1)|(t.b===g.b?1:0),rrExact=(t,g)=>rrStrict(t,g)===63;
const rrRandom=seed=>{let x=seed>>>0;return()=>{x=(1664525*x+1013904223)>>>0;return x/2**32}},rrSample=(xs,r)=>{let p=r()*rrMass(xs);for(const i of xs){p-=rrWeights[i];if(p<0)return i}return xs.at(-1)};
function rrSelectBase(limit=64){const total=rrMass(rrUniverse),metrics=[];for(const index of rrUniverse){let solve=0,matches=0;const outcomes=new Map;for(const ti of rrUniverse){const t=rrCards[ti],w=rrWeights[ti],wm=rrWeak(t,rrCards[index]),sm=rrStrict(t,rrCards[index]),k=`${wm}|${sm}|${rrExact(t,rrCards[index])?1:0}`;if(rrExact(t,rrCards[index]))solve+=w;matches+=popcount(sm)*w;outcomes.set(k,(outcomes.get(k)||0)+w)}let info=0;for(const x of outcomes.values()){const p=x/total;info-=p*Math.log2(p)}metrics.push({index,solve:solve/total,matches:matches/total,info})}const out=new Set([...rrUniverse].sort((a,b)=>rrWeights[b]-rrWeights[a]).slice(0,32));[...metrics].sort((a,b)=>b.solve-a.solve||b.matches-a.matches).slice(0,32).forEach(x=>out.add(x.index));[...metrics].sort((a,b)=>b.info-a.info).slice(0,limit).forEach(x=>{if(out.size<limit)out.add(x.index)});return[...out].slice(0,limit)}
function rrDynamic(state,limit=36){const total=rrMass(state.candidates),old=popcount(state.m),quick=[];for(const index of rrUniverse){if(state.g.has(index))continue;let solve=0,nm=0;const bits=[0,0,0,0,0,0],guess=rrCards[index];for(const ti of state.candidates){const t=rrCards[ti],w=rrWeights[ti],wm=rrWeak(t,guess),sm=rrStrict(t,guess);if(rrExact(t,guess))solve+=w;nm+=(popcount(state.m|sm)-old)*w;for(let b=0;b<6;b++)if(wm&rrBit(b))bits[b]+=w}quick.push({index,solve:solve/total,nm:nm/total,info:bits.reduce((s,x)=>s+rrEnt(x/total),0)})}const out=new Set;[...quick].sort((a,b)=>b.solve-a.solve||b.nm-a.nm).slice(0,20).forEach(x=>out.add(x.index));[...quick].sort((a,b)=>b.info-a.info).slice(0,12).forEach(x=>out.add(x.index));[...state.candidates].sort((a,b)=>rrWeights[b]-rrWeights[a]).slice(0,12).forEach(i=>out.add(i));return[...out].slice(0,limit)}
function rrChoose(state,actions,final,cache){const key=`${final?1:0}|${state.candidates.join(',')}|${[...state.g].sort((a,b)=>a-b).join(',')}`;if(cache.has(key))return cache.get(key);const total=rrMass(state.candidates);if(final){const groups=new Map;for(const i of state.candidates){const c=rrCards[i],s=`${c.b}|${c.a}|${c.r}|${c.nm}|${c.atk}|${c.def}`;if(!groups.has(s))groups.set(s,{index:i,w:0});groups.get(s).w+=rrWeights[i]}const x=[...groups.values()].filter(x=>!state.g.has(x.index)).sort((a,b)=>b.w-a.w)[0];if(x){cache.set(key,x.index);return x.index}}let best=null;const usable=new Set(actions);[...state.candidates].sort((a,b)=>rrWeights[b]-rrWeights[a]).slice(0,24).forEach(i=>usable.add(i));for(const index of usable){if(state.g.has(index))continue;let solve=0,matches=0;const outcomes=new Map,guess=rrCards[index];for(const ti of state.candidates){const t=rrCards[ti],w=rrWeights[ti],wm=rrWeak(t,guess),sm=rrStrict(t,guess),k=`${wm}|${sm}|${wm&1?t.b:''}|${wm&8?t.nm:''}`;if(rrExact(t,guess))solve+=w;matches+=popcount(sm)*w;outcomes.set(k,(outcomes.get(k)||0)+w)}let info=0;for(const x of outcomes.values()){const p=x/total;info-=p*Math.log2(p)}const score=final?[solve/total,matches/total,info]:[info,solve/total,matches/total];if(!best){best={index,score};continue}for(let j=0;j<3;j++){if(Math.abs(score[j]-best.score[j])<1e-12)continue;if(score[j]>best.score[j])best={index,score};break}}cache.set(key,best?.index);return best?.index}
function rrAllocate(t,h,c){const key=`${t}|${h}|${c}`;if(rrAllocationCache.has(key))return rrAllocationCache.get(key);let best={solved:0,matches:0,profile:null};for(const p of rrProfiles){if(p.hints>h||p.challenges>c)continue;let solved=0,matches=0;for(const[k,q]of p.distribution){const[s,m,uh,uc]=k.split('|').map(Number);if(s){const future=rrAllocate(t-1,h-uh,c-uc);solved+=q*(1+future.solved);matches+=q*(6+future.matches)}else matches+=q*m}if(solved>best.solved+1e-12||Math.abs(solved-best.solved)<=1e-12&&matches>best.matches)best={solved,matches,profile:p}}rrAllocationCache.set(key,best);return best}
function rrOpen(targetIndex,r){const f=Math.floor(r()*6),v=rrCards[targetIndex][['b','a','r','n','atk','def'][f]];return{target:targetIndex,candidates:rrUniverse.filter(i=>rrCards[i][['b','a','r','n','atk','def'][f]]===v),k:rrBit(f),m:0,g:new Set,cache:new Map}}
const rrClone=(s,target=s.target)=>({target,candidates:[...s.candidates],k:s.k,m:s.m,g:new Set(s.g),cache:new Map});
function rrHint(s,res,r){const u=[0,1,2,3,4,5].filter(f=>!(s.k&rrBit(f)));if(!res.h||!u.length)return false;const f=u[Math.floor(r()*u.length)],key=['b','a','r','n','atk','def'][f],v=rrCards[s.target][key];res.h--;s.k|=rrBit(f);s.candidates=s.candidates.filter(i=>rrCards[i][key]===v);return true}
function rrChallenge(s,res,index){if(!res.c)return false;res.c--;s.g.add(index);const t=rrCards[s.target],g=rrCards[index];if(rrExact(t,g))return true;const wm=rrWeak(t,g),sm=rrStrict(t,g);s.k|=wm;s.m|=sm;s.candidates=s.candidates.filter(i=>{const c=rrCards[i],w=rrWeak(c,g),st=rrStrict(c,g);return w===wm&&st===sm&&!rrExact(c,g)&&(!(w&1)||c.b===t.b)&&(!(w&8)||c.nm===t.nm)});return false}
function rrContinue(state,res,t,r){let solved=0,matches=0;for(let p=0;p<t&&res.c;p++){let done=false;while(res.c&&!done){const profile=rrAllocate(t-p,res.h,res.c).profile;if(!profile)break;let moved=false;for(let x=0;x<profile.pattern.length&&!done;x++){if(profile.pattern[x]==='0'){moved=rrHint(state,res,r)||moved;continue}const index=rrChoose(state,rrBaseActions,!profile.pattern.slice(x+1).includes('1'),rrFastCache);if(index==null)break;moved=true;done=rrChallenge(state,res,index)}if(!moved)break}if(!done){matches+=popcount(state.m);break}solved++;matches+=6;if(p+1<t)state=rrOpen(rrSample(rrUniverse,r),r)}return[solved,matches]}
function rrValue(initial,res0,t,action,seeds){let out=[0,0];for(const seed of seeds){const r=rrRandom(seed),target=rrSample(initial.candidates,r),s=rrClone(initial,target),res={h:res0.h,c:res0.c};let done=action.type==='hint'?(rrHint(s,res,r),false):rrChallenge(s,res,action.index),v;if(done){v=[1,6];if(t>1){const f=rrContinue(rrOpen(rrSample(rrUniverse,r),r),res,t-1,r);v=[1+f[0],6+f[1]]}}else v=rrContinue(s,res,t,r);out[0]+=v[0]/seeds.length;out[1]+=v[1]/seeds.length}return out}
function resourceDecision(candidates,knownMask,matchedMask,guessed,hints,challenges,puzzle,config,rollouts,diagnostics){diagnostics.solverCalls++;diagnostics.resourceCalls++;const state={target:null,candidates,k:knownMask,m:matchedMask,g:new Set(guessed),cache:new Map},res={h:hints,c:challenges},challengeIndex=rrChoose(state,rrDynamic(state),false,state.cache),options=challengeIndex==null?[]:[{type:'challenge',index:challengeIndex}];if(hints&&knownMask!==63)options.push({type:'hint'});let seed=(Math.random()*2**32)>>>0||0x524f4c4c;const random=()=>{seed=(1664525*seed+1013904223)>>>0;return seed/2**32},seeds=Array.from({length:rollouts},()=>Math.floor(random()*2**32));diagnostics.rolloutSamples+=seeds.length*options.length;const compared=options.map(action=>({action,value:rrValue(state,res,config.puzzles-puzzle+1,action,seeds)})).sort((a,b)=>b.value[0]-a.value[0]||b.value[1]-a.value[1]);return{action:compared[0]?.action,method:'resource-route',compared}}
function decision(cards,weights,universe,candidates,knownMask,matchedMask,guessed,hints,challenges,puzzle,config,diagnostics,cache){
 const key=stateKey(candidates,knownMask,matchedMask,guessed,hints,challenges,puzzle);if(cache.has(key)){diagnostics.cacheHits++;return cache.get(key)}diagnostics.solverCalls++;
 const total=candidates.reduce((s,i)=>s+weights[i],0),old=popcount(matchedMask),quick=[];
 for(const action of universe){if(guessed.has(action))continue;let solve=0,newMatches=0;const bits=[0,0,0,0,0,0],guess=cards[action];for(const t of candidates){const m=matchMask(cards[t],guess),strict=strictMatchMask(cards[t],guess),weight=weights[t];if(isExactAnswer(cards[t],guess))solve+=weight;newMatches+=(popcount(matchedMask|strict)-old)*weight;for(let b=0;b<6;b++)if(m&(1<<b))bits[b]+=weight}quick.push({index:action,solve:solve/total,newMatches:newMatches/total,infoApprox:bits.reduce((s,x)=>s+entropy(x/total),0)})}
 quick.sort((a,b)=>compare([b.solve,b.newMatches,-1],[a.solve,a.newMatches,-1]));let result=null;
 if(puzzle===config.puzzles&&candidates.length<=7&&hints<=4&&challenges<=6){const signatures=new Map();for(const action of universe){if(guessed.has(action))continue;const sig=candidates.map(t=>{const guess=cards[action],target=cards[t],m=matchMask(target,guess);return `${m}:${strictMatchMask(target,guess)}:${isExactAnswer(target,guess)?1:0}:${m&1?target.b:''}:${m&8?target.n:''}`}).join('|');if(!signatures.has(sig))signatures.set(sig,action)}try{result=solveExact({cards,weights,universe:candidates,actions:[...signatures.values()],config:{...config,puzzles:puzzle},puzzle,hints,challenges,candidates,knownMask,matchedMask,guessed:[...guessed],maxStates:160000});diagnostics.exactCalls++}catch(e){if(!String(e.message).startsWith('EXACT_STATE_LIMIT:'))throw e}}
 if(!result){const selected=new Set();quick.slice(0,18).forEach(x=>selected.add(x.index));[...quick].sort((a,b)=>b.infoApprox-a.infoApprox).slice(0,8).forEach(x=>selected.add(x.index));[...candidates].sort((a,b)=>weights[b]-weights[a]).slice(0,8).forEach(i=>selected.add(i));const base={cards,weights,actions:[...selected],hints,challenges,candidates,knownMask,matchedMask,guessed:[...guessed],maxStates:24000,remainingPuzzles:config.puzzles-puzzle+1,resourceModel:{hintChallengeRatio:.61,equivalentCostPerSolve:3.9}};for(const depth of [3,2])try{result=solveRestrictedHorizon({...base,depth});diagnostics[`depth${depth}Calls`]++;break}catch(e){if(!String(e.message).startsWith('HORIZON_STATE_LIMIT:'))throw e}}
 if(!result){result={action:{type:'challenge',index:quick[0].index},method:'fallback'};diagnostics.fallbackCalls++}cache.set(key,result);if(cache.size>4000)cache.delete(cache.keys().next().value);return result;
}
function pulse(completed,total,current,results,config,diagnostics,startedAt,force=false){const now=performance.now();if(!force&&now-lastPulse<250)return;lastPulse=now;postMessage({type:'progress',completed,total,current,results:[...results],diagnostics:{...diagnostics},summary:summarize(results,config.puzzles,diagnostics,startedAt)});}
async function activity(cards,weights,universe,config,diagnostics,cache,round,totalRounds,results,startedAt,algorithm,routeRollouts){let hints=config.totalHints,challenges=config.totalChallenges,solved=0,hintsUsed=0,challengesUsed=0,matchedItems=0;
 for(let puzzle=1;puzzle<=config.puzzles&&challenges>0&&!cancelled;puzzle++){const targetIndex=weightedSample(universe,weights),target=cards[targetIndex],field=Math.floor(Math.random()*6);let knownMask=1<<field;let candidates=universe.filter(i=>read(cards[i],FIELDS[field].key)===read(target,FIELDS[field].key));let matchedMask=0;const guessed=new Set();let puzzleSolved=false;
  while(challenges>0&&!puzzleSolved&&!cancelled){pulse(round,totalRounds,{round:round+1,puzzle,candidates:candidates.length,hints,challenges,hintsUsed,challengesUsed},results,config,diagnostics,startedAt);await new Promise(resolve=>setTimeout(resolve,0));if(cancelled)break;const rec=algorithm==='resource'?resourceDecision(candidates,knownMask,matchedMask,guessed,hints,challenges,puzzle,config,routeRollouts,diagnostics):decision(cards,weights,universe,candidates,knownMask,matchedMask,guessed,hints,challenges,puzzle,config,diagnostics,cache);if(!rec.action||rec.action.type==='stop')break;
   if(rec.action.type==='hint'&&hints>0&&knownMask!==63){const unknown=FIELDS.map((f,i)=>({...f,i})).filter(f=>!(knownMask&f.bit)),chosen=unknown[Math.floor(Math.random()*unknown.length)];knownMask|=chosen.bit;candidates=candidates.filter(i=>read(cards[i],chosen.key)===read(target,chosen.key));hints--;hintsUsed++;diagnostics.hintDecisions++;continue}
   const guessIndex=rec.action.index,guess=cards[guessIndex],mask=matchMask(target,guess),strict=strictMatchMask(target,guess);diagnostics.challengeDecisions++;guessed.add(guessIndex);matchedItems+=popcount(matchedMask|strict)-popcount(matchedMask);matchedMask|=strict;knownMask|=mask;challenges--;challengesUsed++;if(isExactAnswer(target,guess)){solved++;puzzleSolved=true}else candidates=filterCandidates(cards,candidates,guess,mask,target);
  }if(!puzzleSolved)break;
 }return{solved,hintsUsed,challengesUsed,matchedItems};}
self.onmessage=async({data})=>{if(data.type==='cancel'){cancelled=true;return}if(data.type!=='start')return;cancelled=false;const {cards,config,pool,rounds}=data,algorithm=data.algorithm==='resource'?'resource':'stable',routeRollouts=Math.max(2,Math.min(8,Number(data.routeRollouts)||4)),weights=cards.map(c=>pool==='md'?c.wm:c.wa),universe=cards.map((_,i)=>i).filter(i=>weights[i]>0),diagnostics={solverCalls:0,cacheHits:0,exactCalls:0,depth3Calls:0,depth2Calls:0,fallbackCalls:0,resourceCalls:0,rolloutSamples:0,hintDecisions:0,challengeDecisions:0},cache=new Map(),results=[],startedAt=performance.now();if(algorithm==='resource'){rrCards=cards;rrWeights=weights;rrUniverse=universe;rrProfiles=data.routeProfiles||[];rrFastCache=new Map;rrAllocationCache=new Map;rrBaseActions=data.routeBaseActions?.length?data.routeBaseActions:rrSelectBase(64)}postMessage({type:'ready',algorithm,routeRollouts,completed:0,total:rounds,current:{round:1,puzzle:1,candidates:universe.length,hints:config.totalHints,challenges:config.totalChallenges,hintsUsed:0,challengesUsed:0},results:[],diagnostics:{...diagnostics},summary:summarize(results,config.puzzles,diagnostics,startedAt)});try{for(let round=0;round<rounds&&!cancelled;round++){results.push(await activity(cards,weights,universe,config,diagnostics,cache,round,rounds,results,startedAt,algorithm,routeRollouts));pulse(round+1,rounds,{round:round+1,puzzle:config.puzzles,candidates:0,hints:0,challenges:0},results,config,diagnostics,startedAt,true)}postMessage({type:cancelled?'cancelled':'complete',algorithm,routeRollouts,completed:results.length,total:rounds,results:[...results],diagnostics:{...diagnostics},summary:summarize(results,config.puzzles,diagnostics,startedAt)})}catch(error){postMessage({type:'error',algorithm,routeRollouts,message:error.stack||String(error),results:[...results],diagnostics:{...diagnostics}})}};
